    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            cells = [(r, c)]
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        stack.append(p)
                        cells.append(p)
            result.append((color, cells))
    return result


def is_hollow(cells):
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    occupied = set(cells)
    empty = {(r, c) for r in range(r0, r1 + 1)
             for c in range(c0, c1 + 1) if (r, c) not in occupied}
    outside = set()
    stack = []
    for r, c in empty:
        if r in (r0, r1) or c in (c0, c1):
            outside.add((r, c))
            stack.append((r, c))
    while stack:
        r, c = stack.pop()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            p = (r + dr, c + dc)
            if p in empty and p not in outside:
                outside.add(p)
                stack.append(p)
    return bool(empty - outside)


def transform(grid):
    h, w = len(grid), len(grid[0])
    objects = []
    for color, cells in components(grid):
        objects.append({
            'color': color,
            'cells': cells,
            'hollow': is_hollow(cells),
            'r0': min(r for r, c in cells),
            'c0': min(c for r, c in cells),
        })

    out = [[0] * w for _ in range(h)]
    # Hollow shapes rise to the top; solid shapes fall to the bottom.
    for hollow, ordered in (
        (True, sorted((o for o in objects if o['hollow']),
                      key=lambda o: (o['r0'], o['c0']))),
        (False, sorted((o for o in objects if not o['hollow']),
                       key=lambda o: (-o['r0'], o['c0']))),
    ):
        placed = set()
        for obj in ordered:
            cells = obj['cells']
            shift = 0
            while True:
                dr = -1 if hollow else 1
                proposed = {(r + shift + dr, c) for r, c in cells}
                if any(r < 0 or r >= h for r, c in proposed):
                    break
                if proposed & placed:
                    break
                shift += dr
            for r, c in cells:
                rr = r + shift
                out[rr][c] = obj['color']
                placed.add((rr, c))
    return out
